    "createdAt": "2026-09-11T00:00:00Z",
    "html": "<div class=\"island\"></div>\n<div class=\"islandt\"></div>\n<div class=\"hatch\"></div>\n\n<svg height=\"0\" width=\"0\">\n  <filter id=\"octave1\">\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.0004\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o1\"\n    ></feTurbulence>\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.0008\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o2\"\n    ></feTurbulence>\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.0001\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o3\"\n    ></feTurbulence>\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.0018\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o4\"\n    ></feTurbulence>\n\n    <feMerge result=\"finalIsland\">\n      <feMergeNode in=\"o1\"></feMergeNode>\n      <feMergeNode in=\"o3\"></feMergeNode>\n      <feMergeNode in=\"o1\"></feMergeNode>\n      <feMergeNode in=\"o3\"></feMergeNode>\n    </feMerge>\n\n    <feGaussianBlur\n      in=\"finalIsland\"\n      stdDeviation=\"5\"\n      result=\"noiseo\"\n    ></feGaussianBlur>\n\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.0008\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o1\"\n    ></feTurbulence>\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.0016\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o2\"\n    ></feTurbulence>\n\n    <feMerge result=\"noiseo\">\n      <feMergeNode in=\"o2\"></feMergeNode>\n      <feMergeNode in=\"o4\"></feMergeNode>\n      <feMergeNode in=\"noiseo\"></feMergeNode>\n    </feMerge>\n\n    <feGaussianBlur\n      in=\"noiseo\"\n      stdDeviation=\"5\"\n      result=\"noiseo\"\n    ></feGaussianBlur>\n\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.0016\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o1\"\n    ></feTurbulence>\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.002\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o2\"\n    ></feTurbulence>\n\n    <feMerge result=\"noiseo\">\n      <feMergeNode in=\"o1\"></feMergeNode>\n      <feMergeNode in=\"o1\"></feMergeNode>\n      <feMergeNode in=\"noiseo\"></feMergeNode>\n    </feMerge>\n\n    <feGaussianBlur\n      in=\"noiseo\"\n      stdDeviation=\"5\"\n      result=\"noiseo\"\n    ></feGaussianBlur>\n\n    <feDiffuseLighting\n      in=\"noiseo\"\n      surfaceScale=\"12\"\n      diffuseConstant=\"1\"\n      lighting-color=\"#d7bb98\"\n      result=\"lit\"\n    >\n      <feDistantLight azimuth=\"90\" elevation=\"\"></feDistantLight>\n    </feDiffuseLighting>\n\n    <feBlend in=\"lit\" in2=\"SourceGraphic\" mode=\"normal\"></feBlend>\n  </filter>\n\n  <filter id=\"octave2\">\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.0004\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o1\"\n    ></feTurbulence>\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.0008\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o2\"\n    ></feTurbulence>\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.0001\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o3\"\n    ></feTurbulence>\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.0018\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o4\"\n    ></feTurbulence>\n\n    <feMerge result=\"finalIsland\">\n      <feMergeNode in=\"o1\"></feMergeNode>\n      <feMergeNode in=\"o3\"></feMergeNode>\n      <feMergeNode in=\"o1\"></feMergeNode>\n      <feMergeNode in=\"o3\"></feMergeNode>\n    </feMerge>\n\n    <feGaussianBlur\n      in=\"finalIsland\"\n      stdDeviation=\"5\"\n      result=\"noiseo\"\n    ></feGaussianBlur>\n\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.0008\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o1\"\n    ></feTurbulence>\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.0016\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o2\"\n    ></feTurbulence>\n\n    <feMerge result=\"noiseo\">\n      <feMergeNode in=\"o2\"></feMergeNode>\n      <feMergeNode in=\"o4\"></feMergeNode>\n      <feMergeNode in=\"noiseo\"></feMergeNode>\n    </feMerge>\n\n    <feGaussianBlur\n      in=\"noiseo\"\n      stdDeviation=\"5\"\n      result=\"noiseo\"\n    ></feGaussianBlur>\n\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.0016\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o1\"\n    ></feTurbulence>\n    <feTurbulence\n      type=\"fractalNoise\"\n      baseFrequency=\"0.002\"\n      numOctaves=\"8\"\n      seed=\"4\"\n      result=\"o2\"\n    ></feTurbulence>\n\n    <feMerge result=\"noiseo\">\n      <feMergeNode in=\"o1\"></feMergeNode>\n      <feMergeNode in=\"o1\"></feMergeNode>\n      <feMergeNode in=\"noiseo\"></feMergeNode>\n    </feMerge>\n\n    <feGaussianBlur\n      in=\"noiseo\"\n      stdDeviation=\"5\"\n      result=\"noiseo\"\n    ></feGaussianBlur>\n\n    <feDiffuseLighting\n      in=\"noiseo\"\n      surfaceScale=\"12\"\n      diffuseConstant=\"1\"\n      lighting-color=\"#d1bf96\"\n      result=\"lit\"\n    >\n      <feDistantLight azimuth=\"-90\" elevation=\"\"></feDistantLight>\n    </feDiffuseLighting>\n\n    <feBlend in=\"lit\" in2=\"SourceGraphic\" mode=\"normal\"></feBlend>\n  </filter>\n</svg>\n",
