    "css": ".void-pulse {\n  width: 100%;\n  height: 100%;\n  background: linear-gradient(\n    to bottom,\n    rgba(30, 1, 15, 0.2) 0%,\n    rgb(10, 10, 30) 0%,\n    rgba(0, 0, 0, 1) 100%\n  );\n  filter: url(#void-texture);\n  position: relative;\n}\n"
