    "html": "<div class=\"ocean-depths-pattern\">\n  <svg class=\"texture-filter\">\n    <filter id=\"ocean-texture\">\n      <feTurbulence\n        result=\"noise\"\n        numOctaves=\"3\"\n        baseFrequency=\"0.6\"\n        type=\"turbulence\"\n      ></feTurbulence>\n      <feSpecularLighting\n        result=\"specular\"\n        lighting-color=\"#66d9ff\"\n        specularExponent=\"20\"\n        specularConstant=\"0.8\"\n        surfaceScale=\"2\"\n        in=\"noise\"\n      >\n        <fePointLight z=\"100\" y=\"120\" x=\"120\"></fePointLight>\n      </feSpecularLighting>\n      <feComposite\n        result=\"litNoise\"\n        operator=\"over\"\n        in2=\"SourceGraphic\"\n        in=\"specular\"\n      ></feComposite>\n      <feBlend mode=\"screen\" in2=\"litNoise\" in=\"SourceGraphic\"></feBlend>\n    </filter>\n  </svg>\n</div>\n",
    "css": ".ocean-depths-pattern {\n  width: 100%;\n  height: 100%;\n  background: linear-gradient(\n    180deg,\n    #0a1e2b,\n    #1a3b4a 50%,\n    #092934 90%,\n    #032630\n  );\n  filter: url(#ocean-texture);\n}\n"
