    "html": "<div class=\"circuit-wrapper\">\n  <div class=\"circuit-background\"></div>\n</div>\n",
    "css": ".circuit-wrapper {\n  min-height: 100%;\n  width: 100%;\n  position: relative;\n  background-color: white;\n}\n\n.circuit-background {\n  position: absolute;\n  top: 0;\n  right: 0;\n  bottom: 0;\n  left: 0;\n  z-index: 0;\n  pointer-events: none;\n  background-image: repeating-linear-gradient(\n      0deg,\n      transparent,\n      transparent 19px,\n      rgba(75, 85, 99, 0.08) 19px,\n      rgba(75, 85, 99, 0.08) 20px,\n      transparent 20px,\n      transparent 39px,\n      rgba(75, 85, 99, 0.08) 39px,\n      rgba(75, 85, 99, 0.08) 40px\n    ),\n    repeating-linear-gradient(\n      90deg,\n      transparent,\n      transparent 19px,\n      rgba(75, 85, 99, 0.08) 19px,\n      rgba(75, 85, 99, 0.08) 20px,\n      transparent 20px,\n      transparent 39px,\n      rgba(75, 85, 99, 0.08) 39px,\n      rgba(75, 85, 99, 0.08) 40px\n    ),\n    radial-gradient(\n      circle at 20px 20px,\n      rgba(55, 65, 81, 0.12) 2px,\n      transparent 2px\n    ),\n    radial-gradient(\n      circle at 40px 40px,\n      rgba(55, 65, 81, 0.12) 2px,\n      transparent 2px\n    );\n  background-size:\n    40px 40px,\n    40px 40px,\n    40px 40px,\n    40px 40px;\n}\n"
